// Generates matrix/linear-eng-1881.md (the ENG-1881 description, as raw markdown) from cases.json.
// Decision questions come from the "## <ID>: <question>" headings in decisions.md.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const raw = readFileSync(join(here, "cases.json"));
const sha = createHash("sha256").update(raw).digest("hex");
const cases = JSON.parse(raw.toString("utf8"));
const decisionsMd = readFileSync(join(here, "decisions.md"), "utf8");
const questions = Object.fromEntries(
  [...decisionsMd.matchAll(/^## ([A-Z]+-\d+(?: and [A-Z]+-\d+)?): (.+)$/gm)].flatMap(([, ids, q]) =>
    ids.split(" and ").map((id) => [id, q.trim()]),
  ),
);

const PAGE = "https://claude.ai/artifact/PPJhCiaXpp7LB7C11GRpTf";
const AREAS = [
  ["PUB", "Share and publish"], ["DSC", "Discovery and access"], ["TXT", "Content fidelity"],
  ["TTL", "Titles and node types"], ["SRC", "Referenced source"], ["AST", "Assets"],
  ["UPD", "Edits and refresh"], ["DEL", "Deletion and unsharing"], ["REL", "Relations"],
  ["SCH", "Relation and node types"], ["CNV", "Canvas"], ["COL", "Collaboration"],
  ["RND", "Round trips"], ["UX", "Dialogs and panels"], ["SCL", "Scale and resilience"],
  ["SEC", "Access control (local database only)"],
];
const flat = (s) => String(s).replace(/\s+/g, " ").trim();
const dirs = (c) => c.dirs.map((d) => (d === "DB" ? "local DB" : d)).join(", ");
const expectation = (c) => {
  if (c.rating === "decide") return "Needs a decision (see Open decisions).";
  const e = flat(c.expected);
  return c.rating === "gap" ? `Known gap. ${e}` : e;
};
const line = (c) => `- **${c.id}** ${flat(c.title)} (${c.pri}; ${dirs(c)}${c.iso ? "; isolated" : ""}): ${expectation(c)}`;

const count = (k, v) => cases.filter((c) => c[k] === v).length;
const journeys = cases.filter((c) => c.smoke);
const decide = cases.filter((c) => c.rating === "decide");

const body = [
  "## Problem",
  "",
  "* Some MVP0 behavior may not be reliably automated in plugin runtime tests.",
  "* Internal testers need a clear script with expected results.",
  "",
  "## Scope",
  "",
  `* The script is the push/pull test matrix: ${cases.length} cases in ${AREAS.length + 1} areas, each with steps, an expected result, the directions it runs in (RR, RO, OR, OO; three-letter codes name the owner, contributor and consumer spaces), a method and the evidence a pass needs.`,
  "* It covers share, discover, import, refresh, relations, assets and access boundaries, for Roam to Obsidian, Obsidian to Roam, and each app to itself. Authorized paths and unauthorized paths (DSC, SEC) are both included.",
  `* Known gaps are marked in each line below (${count("rating", "gap")} cases). Cases that need a product decision say so and are listed under Open decisions (${decide.length}).`,
  "* Isolated cases break or delete data on purpose and run only on throwaway spaces and a throwaway group. Access-control cases (SEC) and local-database cases run only against a local database, by an engineer.",
  "* Ratings in the matrix are predictions from reading the code, not results. Results belong to ENG-1883, one record per candidate run.",
  "",
  "## Journeys",
  "",
  "Run these four first on every candidate. They are the smoke checks.",
  "",
  ...journeys.map(line),
  "",
  "## Cases by area",
  "",
  ...AREAS.flatMap(([code, name]) => {
    const list = cases.filter((c) => c.area === code);
    return list.length ? [`### ${name} (${code})`, "", ...list.map(line), ""] : [];
  }),
  "## Open decisions",
  "",
  "Each needs an agreed expected result before its case can pass or fail.",
  "",
  ...decide.map((c) => `- **${c.id}** ${questions[c.id] ?? flat(c.title)}`),
  "",
  "## Where the full list lives",
  "",
  `* Matrix page, with steps, expected results, code evidence, filters and a copy-to-sheet button: ${PAGE} (private until shared).`,
  `* Canonical cases: \`matrix/cases.json\` in the validation folder, sha256 \`${sha}\`. The page, the bug-bash sheet rows and this description are generated from it.`,
  "",
  "## Done When",
  "",
  "* Internal testers can run the MVP0 QA script without extra engineering context.",
  "* The script covers authorized and unauthorized paths.",
  "* Known manual-only gaps are clearly marked.",
  "",
  "## Out of Scope",
  "",
  "* Running the QA script.",
  "* Creating new automated tests.",
  "* Resolving bugs found during QA.",
  "",
  "## Notes",
  "",
  "* Functional requirement: [F15: Test and fixture coverage](<https://roamresearch.com/#/app/discourse-graphs/page/JLxa_X2HX>).",
  "* Depends on [ENG-1878](<https://linear.app/discourse-graphs/issue/ENG-1878/consolidate-mvp0-cross-app-fixtures-for-internal-validation>).",
  "* This should become the playbook for the final internal validation run.",
].join("\n");

const out = [
  "# ENG-1881 description",
  "",
  `Generated by \`node matrix/linear.mjs\` from \`matrix/cases.json\` (sha256 \`${sha}\`). Not posted. Paste the block below into the ENG-1881 description.`,
  "",
  "Kept from the current ticket: Problem, Done When, Out of Scope and Notes, word for word. The Solution section is replaced by Scope and the case index.",
  "",
  "````markdown",
  body,
  "````",
  "",
].join("\n");
writeFileSync(join(here, "linear-eng-1881.md"), out);
console.log(`cases=${cases.length} journeys=${journeys.length} decisions=${decide.length} questions=${Object.keys(questions).length} bytes=${Buffer.byteLength(body)}`);

