// Runs the published page's script against a tiny DOM stub and checks the direction tokens render.
import { readFileSync } from "node:fs";

const html = readFileSync("/mnt/data/projects/dg-validation-eng-1883/matrix/push-pull-test-matrix.html", "utf8");
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];

class Node {
  constructor(tag) { this.tag = tag; this.children = []; this.attrs = {}; this.className = ""; this._text = ""; this.listeners = {}; this.hidden = false; this.style = {}; this.value = ""; this.open = false; }
  append(...cs) { for (const c of cs) this.children.push(typeof c === "string" ? { text: c } : c); }
  appendChild(c) { this.append(c); return c; }
  setAttribute(k, v) { this.attrs[k] = v; }
  addEventListener(k, f) { this.listeners[k] = f; }
  querySelectorAll() { return []; }
  querySelector() { return null; }
  set textContent(v) { this._text = v; this.children = []; }
  get textContent() { return this._text + this.children.map((c) => c.text ?? c.textContent ?? "").join(""); }
  set innerHTML(v) { this._text = v; this.children = []; }
  get classList() { return { add() {}, remove() {}, toggle() {} }; }
}
const byId = {};
globalThis.document = {
  getElementById: (id) => (byId[id] ??= new Node("div")),
  createElement: (t) => new Node(t),
  createTextNode: (t) => ({ text: t }),
  querySelectorAll: () => [],
  addEventListener() {},
  documentElement: new Node("html"),
};
globalThis.localStorage = { getItem: () => null, setItem() {} };
globalThis.window = globalThis;
globalThis.navigator = { clipboard: { writeText: async () => {} } };

new Function(script)();

const main = byId.matrix;
const flatText = (n) => (n.text ?? "") + (n._text ?? "") + (n.children || []).map(flatText).join("");
const all = [];
const walk = (n) => { all.push(n); (n.children || []).forEach(walk); };
walk(main);
const cases = all.filter((n) => n.tag === "details");
console.log("rendered cases:", cases.length);
for (const id of ["REL-13", "REL-14", "REL-15", "COL-08", "SEC-04"]) {
  const det = cases.find((d) => d.attrs.id === id);
  const dirs = [];
  const w2 = (n) => { if (n.className === "dir") dirs.push(`${flatText(n)} [${n.title}]`); (n.children || []).forEach(w2); };
  w2(det);
  console.log(id, "->", dirs.join(" | "));
}

