.empty { padding: 24px 4px; color: var(--muted); }

footer { font-size: 13px; color: var(--muted); display: flex; flex-direction: column; gap: 6px; max-width: 86ch; border-top: 1px solid var(--line); padding-top: 16px; }

@media (max-width: 900px) {
