// Collapse whitespace, and put tokens like import/<space>/ in inline code so Linear doesn't read them as HTML.
const flat = (s) =>
  String(s)
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[^\s`]*<[^>\s]+>[^\s,;)`]*/g, (m) => `\`${m}\``);

.replace(/[^\s`(“"]*<[^>\s]+>[^\s,;:)`”"]*/g, (m) => {
  const trail = m.match(/\.+$/)?.[0] ?? "";
  return `\`${m.slice(0, m.length - trail.length)}\`${trail}`;
});

