# Decisions settled by the project's own scope (P-DIS-166 description: use cases and non-goals) and existing tickets.
GM = "Sharing group management (P-ENG-170)"

CHANGES = {
    "TXT-06": {
        "expected": "Refresh replaces the page with the source content without making a duplicate. Local edits and child blocks are removed, and block references into the old blocks stop resolving.",
        "src": "Project UC4, UC5 (changes to an imported node are overwritten)",
        "rating": "pass",
        "why": "Settled by the project's use cases: Refresh overwrites the imported node. The candidate adds the new content, then deletes every old block, so block ids change. Keeping block ids isn't v0 work.",
    },
    "REL-07": {
        "expected": "Known gap for v0: Refresh doesn't bring the new relation; it arrives only with a dialog import.",
        "src": "ENG-1852 (destination refresh and relation freshness out of scope); project UC5",
        "rating": "gap",
    },
    "REL-08": {
        "expected": "Known gap for v0: the relation is shared only when one of its endpoints is published again.",
        "src": "ENG-1852 (relation freshness out of scope); project UC6",
        "rating": "gap",
    },
    "UPD-09": {
        "expected": "Known gap for v0: nothing shows that a newer version exists; the user refreshes explicitly.",
        "src": "Project UC5 and non-goals (no background pull); ENG-1875 adds the source-modified time to the Roam title area",
        "rating": "gap",
    },
    "TTL-11": {
        "expected": "The second import fails with a message naming the existing page, and nothing is overwritten. Keeping both isn't possible in v0.",
        "src": "ENG-1858, ENG-1859 (title-collision UX out of scope)",
        "rating": "pass",
        "why": "Both decorate to the same page title, so the second import fails: “A page titled … already exists and was not imported from …”. Final collision handling is out of v0 scope.",
    },
    "TXT-04": {
        "expected": "Known gap for v0: links and tags arrive as Roam page references as written, and [[Other|alias]] isn't converted to Roam's alias form.",
        "src": "Project non-goal (perfect formatting preservation); ENG-1882 (fidelity limits)",
        "rating": "gap",
        "why": "Links and tags reach Roam's markdown import unchanged, so Roam treats them as page references and may create empty pages. Formatting edge cases are a project non-goal, and ENG-1882 documents the limits.",
    },
    "AST-08": {
        "expected": "Assets land where the Obsidian reference flow puts them: under import/<space>/, relative to the note's folder when the asset sits in it, otherwise at its source vault path.",
        "src": "Project goal (MVP0 mirrors the Obsidian reference behavior)",
        "rating": "pass",
        "why": "Settled by the reference flow. An asset already imported with the same hash keeps its path, and a name clash gets a suffix.",
    },
    "PUB-04": {
        "expected": "Known gap for v0: unchecking an already-shared group doesn't unshare the node, because there is no unshare.",
        "src": "Project use cases (none covers unsharing); ENG-1968",
        "rating": "gap",
    },
    "DEL-03": {
        "expected": "Known gap for v0: there's no way to stop sharing a node with a group. Deleting the node removes it from other spaces.",
        "src": "Project use cases (none covers unsharing)",
        "rating": "gap",
    },
    "PUB-11": {
        "src": "ENG-2141 (decision: omit the Source and warn); ENG-2232 (publishing the Source too, post-v0)",
    },
    "DSC-06": {"src": f"Not specified; owned by {GM}"},
    "SEC-03": {"src": f"Not specified; owned by {GM}"},
    "SEC-04": {"src": f"Not specified (the earlier “Access model” source described the code, not a policy); owned by {GM}"},
    "UPD-04": {"src": "ENG-1861, ENG-1877"},
}

ADDITIONS = []

