input.content:
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const casesRaw = readFileSync(join(here, "cases.json"));
const casesSha = createHash("sha256").update(casesRaw).digest("hex");
const cases = JSON.parse(casesRaw.toString("utf8"));
const bugs = JSON.parse(readFileSync(join(here, "bugs.json"), "utf8"));
const template = readFileSync(join(here, "template.html"), "utf8");

const inline = (v) => JSON.stringify(v).replace(/</g, "\\u003c");
const html = template.replace("/*__CASES__*/[]", inline(cases)).replace("/*__BUGS__*/[]", inline(bugs));
writeFileSync(join(here, "push-pull-test-matrix.html"), html);

const AREAS = {
  JRN: "Journeys", PUB: "Share and publish", DSC: "Discovery and access", TXT: "Content fidelity",
  TTL: "Titles and node types", SRC: "Referenced source", AST: "Assets", UPD: "Edits and refresh",
  DEL: "Deletion and unsharing", REL: "Relations", SCH: "Relation and node types", CNV: "Canvas",
  COL: "Collaboration", RND: "Round trips", UX: "Dialogs and panels", SCL: "Scale and resilience",
  SEC: "Access control (local database only)",
};
const RATINGS = { risk: "High risk", decide: "Needs a decision", gap: "Known gap", pass: "Expected to pass", unknown: "Unknown" };
const METHODS = { bash: "Real-product bug bash", db: "Local database test", auto: "Automated conversion test" };
const EVIDENCE = { shot: "Screenshot", log: "Assertion output or log", receipt: "Written receipt" };
const DIR_TEXT = {
  RR: "from Roam to Roam", RO: "from Roam to Obsidian", OR: "from Obsidian to Roam", OO: "from Obsidian to Obsidian",
  "3S": "across three spaces", DB: "local database",
};
const PLATFORM = { R: "Roam", O: "Obsidian" };
// Three-letter codes name the platforms of A (owner), B (contributor) and C (consumer).
const dirText = (d) =>
  DIR_TEXT[d] ?? (/^[RO]{3}$/.test(d) ? `A ${PLATFORM[d[0]]}, B ${PLATFORM[d[1]]}, C ${PLATFORM[d[2]]}` : d);
const cell = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ").trim();
const header = ["Case", "subcase", "expected behavior", "PIC with writing expected behavior", "pass?", "Actual behavior (if failed)", "Test by", "Notes", "ID", "Rating", "Method", "Evidence if it passes", "Priority", "Candidate", "Environment", "Observed result"];
const rows = [header.join("\t")];
for (const c of cases) {
  const expected = c.prov ? `${c.expected} (${c.prov})` : c.expected;
  for (const d of c.dirs) {
    rows.push([
      `${AREAS[c.area]}: ${c.title}`, dirText(d), `${expected} (Source: ${c.src}) Steps: ${c.steps}`,
      "", "", "", "", c.why, c.id, RATINGS[c.rating], METHODS[c.method] + (c.iso ? " (isolated)" : ""),
      EVIDENCE[c.evidence], c.pri, "b3796a70", "", "",
    ].map(cell).join("\t"));
  }
}
writeFileSync(join(here, "push-pull-test-matrix.tsv"), rows.join("\n") + "\n");

// bugs.md: the same failure list as the page, plus the rows where the code doesn't yet match a provisional decision.
const md = (s) => String(s).replace(/\|/g, "\\|");
const SEEN = { live: "Real system", code: "Code test only" };
const byId = Object.fromEntries(cases.map((c) => [c.id, c]));
const bugLines = bugs.map((b) =>
  `| ${b.case} | ${b.severity} | ${SEEN[b.seen]} | ${md(b.title)} | ${md(b.expected)} (${md(b.expSrc)}) | ${md(b.actual)} | ${b.ticket || "none"} | ${b.evidence.map((e) => `\`${e}\``).join(", ")} |`,
);
const provMismatch = cases.filter((c) => c.prov && c.rating === "risk");
const bugsMd = [
  "# Failures found so far",
  "",
  `Generated by \`node matrix/build.mjs\` from \`matrix/bugs.json\`. Candidate \`b3796a70\`, matrix revision \`${casesSha}\`.`,
  "",
  "- **Real system:** seen in the real apps or the local database during a run.",
  "- **Code test only:** a unit test against the candidate's real code fails the case's expected result. Not yet seen in the apps.",
  "- Each row's expected result comes from a ticket, a use case or basic data safety, named in brackets.",
  "",
  "| Case | Severity | Seen in | Problem | Expected (source) | Actual | Ticket | Evidence |",
  "| --- | --- | --- | --- | --- | --- | --- | --- |",
  ...bugLines,
  "",
  "## Code doesn't match a provisional decision yet",
  "",
  "These expected results come from provisional decisions that Sid took on 2026-09-25 for team review. The code doesn't do them yet. They are changes to build, not regressions.",
  "",
  ...provMismatch.map((c) => `- **${c.id}** ${md(c.title)}: ${md(c.expected)}`),
  "",
  "## Not counted here",
  "",
  "- High-risk rows that no run or test has checked yet. They are predictions, not failures.",
  "- SEC-01: inconclusive in run 1, because the legitimate-member control also failed.",
  "- An Obsidian relation that had its sharing grants before its database row, seen once in run 1. It needs a clean retest.",
  "",
].join("\n");
writeFileSync(join(here, "bugs.md"), bugsMd);
for (const b of bugs) if (!byId[b.case]) throw new Error(`bugs.json names unknown case ${b.case}`);
console.log(`cases=${cases.length} tsvRows=${rows.length - 1} bugs=${bugs.length} htmlBytes=${Buffer.byteLength(html)}`);

