// Shared results: one db document per case and direction, results/<CASE>__<DIR>.
const RESULTS = {};
const resultEls = {};
const resultBadges = {};
const bugResultEls = {};
const STATUS = { pass: "Pass", fail: "Fail", blocked: "Blocked" };
const STATUS_OPTIONS = [["", "Not run"], ["pass", "Pass"], ["fail", "Fail"], ["blocked", "Blocked"]];
const rid = (id, d) => id + "__" + d;
let NAMES = {};
let DBR = null, USERCAP = null, MYID = null, readOnly = false, dbMessage = "Loading shared results…";
const writeQueue = {};

function setDbNote(text) {
  dbMessage = text;
  const n = document.getElementById("dbNote");
  if (n) n.textContent = text;
}
function canMark() { return !!DBR && !readOnly; }
function when(iso) { try { return new Date(iso).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }); } catch (e) { return ""; } }

function paintResults(caseId) {
  const c = CASES.find(x => x.id === caseId);
  if (!c) return;
  const badge = resultBadges[caseId];
  if (badge) {
    const marks = c.dirs.map(d => RESULTS[rid(caseId, d)]).filter(r => r && r.status);
    const fails = marks.filter(r => r.status === "fail").length;
    badge.className = "rbadge" + (fails ? " fail" : marks.length ? " done" : "");
    badge.textContent = marks.length ? (fails ? fails + " failed" : marks.length + "/" + c.dirs.length + " tested") : "";
  }
  const box = resultEls[caseId];
  if (!box || box.contains(document.activeElement)) return;
  box.textContent = "";
  if (!DBR) { box.append(el("span", { class: "rby", text: dbMessage })); return; }
  c.dirs.forEach(d => {
    const key = rid(caseId, d);
    const r = RESULTS[key];
    const row = el("div", { class: "rrow" });
    row.append(dirToken(d));
    if (canMark()) {
      const sel = el("select", { id: "res-" + key, "aria-label": "Result for " + caseId + " " + dirText(d) });
      STATUS_OPTIONS.forEach(([v, l]) => {
        const o = el("option", { value: v, text: l });
        if (((r && r.status) || "") === v) o.selected = true;
        sel.append(o);
      });
      const note = el("input", { type: "text", id: "note-" + key, placeholder: "What happened (optional)", "aria-label": "Notes for " + caseId + " " + dirText(d) });
      note.value = (r && r.note) || "";
      sel.addEventListener("change", () => saveResult(caseId, d, sel.value, note.value));
      note.addEventListener("change", () => saveResult(caseId, d, sel.value, note.value));
      row.append(sel, note);
    } else {
      row.append(el("span", { class: "rstat " + ((r && r.status) || "none"), text: r && STATUS[r.status] ? STATUS[r.status] : "Not run" }));
      if (r && r.note) row.append(el("span", { class: "rtext", text: r.note }));
    }
    if (r) row.append(el("span", { class: "rby", text: (NAMES[r.by] || "Someone") + ", " + when(r.at) }));
    box.append(row);
  });
}
function paintBugResults() {
  Object.entries(bugResultEls).forEach(([caseId, td]) => {
    const c = CASES.find(x => x.id === caseId);
    td.textContent = "";
    if (!c) return;
    const marks = c.dirs.map(d => [d, RESULTS[rid(caseId, d)]]).filter(([, r]) => r && r.status);
    if (!marks.length) { td.append(el("span", { class: "rby", text: DBR ? "Not run" : "" })); return; }
    marks.forEach(([d, r]) => td.append(el("div", { class: "rline" }, [dirToken(d), el("span", { class: "rstat " + r.status, text: STATUS[r.status] })])));
  });
}
function paintSummary() {
  const total = CASES.reduce((n, c) => n + c.dirs.length, 0);
  const marks = Object.values(RESULTS).filter(r => r && r.status);
  const count = s => marks.filter(r => r.status === s).length;
  const s = document.getElementById("resultsSummary");
  if (!s) return;
  s.textContent = DBR
    ? "Shared results: " + marks.length + " of " + total + " case-direction rows marked (" + count("pass") + " pass, " + count("fail") + " fail, " + count("blocked") + " blocked)."
    : dbMessage;
}
function repaintAllResults() {
  Object.keys(resultEls).forEach(paintResults);
  paintBugResults();
  paintSummary();
}
async function refreshNames() {
  if (!USERCAP) return;
  const ids = [...new Set(Object.values(RESULTS).map(r => r && r.by).filter(Boolean))];
  if (!ids.length) return;
  const ps = await USERCAP.profiles(ids);
  const next = {};
  ids.forEach(id => { next[id] = (ps[id] && ps[id].name) || ""; });
  NAMES = next;
}
function saveResult(caseId, d, status, note) {
  if (!canMark()) return;
  const key = rid(caseId, d);
  const ref = DBR.collection("results").doc(key);
  const text = String(note || "").trim().slice(0, 2000);
  writeQueue[key] = (writeQueue[key] || Promise.resolve()).then(async () => {
    try {
      if (!status && !text) await ref.delete();
      else await ref.set({ case: caseId, dir: d, status: status || "", note: text, by: MYID, at: new Date().toISOString() });
    } catch (e) {
      if (e && e.code === "invalid_argument") {
        readOnly = true;
        setDbNote("You can see results but not mark them. Ask Sid for Contributor access to this page.");
        repaintAllResults();
      } else {
        setDbNote("Couldn't save the result for " + caseId + " " + d + ". Try again.");
      }
    }
  });
}
async function startResults() {
  const use = window.claude && typeof window.claude.use === "function" ? n => window.claude.use(n) : async () => null;
  const [db, user] = await Promise.all([use("db"), use("user")]);
  USERCAP = user;
  if (!db) { setDbNote("Shared results aren't available in this view. Open the page in Claude while signed in."); repaintAllResults(); return; }
  DBR = db;
  MYID = user ? await user.id() : null;
  const may = user ? await user.can("data.write") : null;
  if (may === false) readOnly = true;
  setDbNote(readOnly ? "You can see results but not mark them. Ask Sid for Contributor access to this page." : "Mark results in All cases: open a case and pick a result for each direction. Everyone sees marks live.");
  repaintAllResults();
  db.collection("results").onSnapshot(async snap => {
    const changed = new Set();
    snap.docChanges().forEach(ch => {
      const id = ch.doc.id;
      if (ch.type === "removed") delete RESULTS[id];
      else RESULTS[id] = ch.doc.data();
      changed.add(id.split("__")[0]);
    });
    await refreshNames();
    changed.forEach(paintResults);
    paintBugResults();
    paintSummary();
  }, () => setDbNote("Shared results stopped updating. Reload the page to reconnect."));
}

