# Validate the rewrite outputs and turn them into an edits module for casefmt.py.
import glob
import json
import sys

D = "/tmp/claude-1000/-mnt-data-projects-discourse-graph/497ad028-c9de-4d45-a105-68b6b12aec9f/scratchpad/rewrite/"
cases = json.load(open("/mnt/data/projects/dg-validation-eng-1883/matrix/cases.json", encoding="utf8"))
byid = {c["id"]: c for c in cases}
out = {}
problems = []
for f in sorted(glob.glob(D + "out-*.json")):
    for r in json.load(open(f, encoding="utf8")):
        cid = r.get("id")
        if cid not in byid:
            problems.append(f"{f}: unknown id {cid}")
            continue
        if cid in out:
            problems.append(f"{f}: duplicate id {cid}")
        extra = set(r) - {"id", "summary", "expected", "steps", "why"}
        if extra:
            problems.append(f"{cid}: extra fields {extra}")
        for k in ("summary", "expected", "why"):
            if not isinstance(r.get(k), str) or not r[k].strip():
                problems.append(f"{cid}: bad {k}")
        if not isinstance(r.get("steps"), list) or not r["steps"] or not all(isinstance(s, str) and s.strip() for s in r["steps"]):
            problems.append(f"{cid}: bad steps")
        text = json.dumps(r, ensure_ascii=False)
        if "—" in text:
            problems.append(f"{cid}: em dash")
        out[cid] = r
missing = [c["id"] for c in cases if c["id"] not in out]
print("rewritten", len(out), "of", len(cases), "missing", missing)
for p in problems:
    print("PROBLEM", p)
if "--write" in sys.argv and not problems and not missing:
    changes = {cid: {"summary": r["summary"], "expected": r["expected"], "steps": r["steps"], "why": r["why"]} for cid, r in out.items()}
    json.dump(changes, open(D + "changes.json", "w", encoding="utf8"), ensure_ascii=False)
    open(D + "edits_rewrite.py", "w").write(
        "import json\nCHANGES = json.load(open(%r, encoding='utf8'))\nADDITIONS = []\n" % (D + "changes.json")
    )
    print("wrote edits_rewrite.py")

import glob
