import re

D = "/tmp/claude-1000/-mnt-data-projects-discourse-graph/497ad028-c9de-4d45-a105-68b6b12aec9f/scratchpad/rewrite/"
cases = {c["id"]: c for c in json.load(open("/mnt/data/projects/dg-validation-eng-1883/matrix/cases.json", encoding="utf8"))}
new = {}
for f in glob.glob(D + "out-*.json"):
    for r in json.load(open(f, encoding="utf8")):
        new[r["id"]] = r

TOKEN = re.compile(r"(ENG-\d+|PR #\d+|#\d{3,4}|UC\d|[A-Za-z]+\.(?:ts|tsx|sql|json|md)(?::[\d, -]+)?|“[^”]{2,80}”|\b\d[\d,.]*\s?(?:MiB|KiB|s|minutes|%)\b|[A-Z]{2,4}-\d{2})")
issues = 0
for cid, c in cases.items():
    r = new[cid]
    old_text = " ".join([c["steps"] if isinstance(c["steps"], str) else " ".join(c["steps"]), c["expected"], c["why"]])
    new_text = " ".join([r["summary"], " ".join(r["steps"]), r["expected"], r["why"]])
    missing = []
    for t in set(TOKEN.findall(old_text)):
        core = t.split(":")[0] if t.endswith((".ts", ".tsx")) is False and ":" in t and not t.startswith("“") else t
        if core not in new_text:
            missing.append(t)
    if c.get("prov") and r["expected"] != c["expected"]:
        missing.append("PROVISIONAL EXPECTED CHANGED")
    if missing:
        issues += 1
        print(cid, "missing:", missing)
print("cases with possibly dropped tokens:", issues)

